import React, { useState } from "react";
import api from "../api/axios";
import { Link, useNavigate } from "react-router-dom";

function ResetPassword() {
	const [formData, setFormData] = useState({
		user_name: "@mussa",
		new_password: "",
		confirm_password: "",
	});

	const [loading, setLoading] = useState(false);
	const [status, setStatus] = useState({ type: "", message: "" });
	const navigate = useNavigate();

	const handleChange = (e) => {
		setFormData({
			...formData,
			[e.target.name]: e.target.value,
		});
	};

	const handleReset = async (e) => {
		e.preventDefault();
		setLoading(true);
		setStatus({ type: "", message: "" });

		if (formData.new_password !== formData.confirm_password) {
			setStatus({
				type: "danger",
				message: "❌ Passwords do not match. Please re-enter.",
			});
			setLoading(false);
			return;
		}

		if (formData.new_password.length < 4) {
			setStatus({
				type: "danger",
				message: "❌ Password must be at least 4 characters long.",
			});
			setLoading(false);
			return;
		}

		try {
			const res = await api.post("/users/reset-password", {
				user_name: formData.user_name,
				new_password: formData.new_password,
				confirm_password: formData.confirm_password,
			});

			setStatus({
				type: "success",
				message: `✅ ${res.data?.message || "Password reset successfully!"}`,
			});

			setTimeout(() => {
				navigate("/add-product");
			}, 1800);
		} catch (err) {
			console.error("Error resetting password:", err);
			setStatus({
				type: "danger",
				message:
					err.response?.data?.message ||
					"❌ Failed to reset password. Please verify the username.",
			});
		} finally {
			setLoading(false);
		}
	};

	return (
		<div className="reset-password-page py-5 my-5" style={{ minHeight: "80vh", paddingTop: "80px" }}>
			<div className="container">
				<div className="row justify-content-center">
					<div className="col-12 col-md-7 col-lg-5">
						<div
							className="card shadow-lg p-4 p-md-5"
							style={{
								borderRadius: "24px",
								background: "#ffffff",
								border: "1px solid #e5e5ea",
							}}
						>
							<div className="text-center mb-4">
								<div style={{ fontSize: "40px", marginBottom: "8px" }}>🔑</div>
								<h2 className="fw-bold text-dark">Reset Password</h2>
								<p className="text-muted small">
									Update your internal administrator password securely (hashed with bcrypt in MySQL).
								</p>
							</div>

							{status.message && (
								<div className={`alert alert-${status.type} text-center small py-2`} role="alert">
									{status.message}
								</div>
							)}

							<form onSubmit={handleReset}>
								{/* Username */}
								<div className="mb-3">
									<label className="form-label fw-semibold small text-muted">Admin Username</label>
									<input
										type="text"
										name="user_name"
										className="form-control py-2"
										value={formData.user_name}
										onChange={handleChange}
										required
										placeholder="e.g. @mussa"
									/>
								</div>

								{/* New Password */}
								<div className="mb-3">
									<label className="form-label fw-semibold small text-muted">New Password</label>
									<input
										type="password"
										name="new_password"
										className="form-control py-2"
										value={formData.new_password}
										onChange={handleChange}
										required
										placeholder="Enter new password"
									/>
								</div>

								{/* Confirm New Password */}
								<div className="mb-4">
									<label className="form-label fw-semibold small text-muted">Confirm New Password</label>
									<input
										type="password"
										name="confirm_password"
										className="form-control py-2"
										value={formData.confirm_password}
										onChange={handleChange}
										required
										placeholder="Repeat new password"
									/>
								</div>

								<button
									type="submit"
									disabled={loading}
									className="btn btn-primary w-100 py-2 rounded-pill fw-semibold"
									style={{ background: "#0071e3", borderColor: "#0071e3" }}
								>
									{loading ? "Resetting Password..." : "Update Password"}
								</button>

								<div className="d-flex justify-content-between align-items-center mt-4 pt-2 border-top">
									<Link to="/add-product" className="text-muted small text-decoration-none">
										&larr; Back to Admin Sign In
									</Link>
									<Link to="/" className="text-muted small text-decoration-none">
										Home Store
									</Link>
								</div>
							</form>
						</div>
					</div>
				</div>
			</div>
		</div>
	);
}

export default ResetPassword;
